class Person:
    def breathe(self): print("Breathing")

class Student(Person):                  # single
    def study(self): print("Studying")

class DiplomaStudent(Student):          # multilevel
    def lab(self): print("Doing lab work")

class Teacher(Person):                  # hierarchical (Person -> Student, Teacher)
    def teach(self): print("Teaching")

class Phone:
    def call(self): print("Calling")

class Camera:
    def photo(self): print("Click!")

class SmartPhone(Phone, Camera):        # multiple
    pass

d = DiplomaStudent(); d.breathe(); d.study(); d.lab()
t = Teacher(); t.breathe(); t.teach()
sp = SmartPhone(); sp.call(); sp.photo()

class Calculator:
    def add(self, a, b, c=0):          # overloading-like (default argument)
        return a + b + c

class Animal:
    def sound(self): return "..."

class Cat(Animal):
    def sound(self): return "Meow"     # overriding

calc = Calculator()
print(calc.add(2, 3), calc.add(2, 3, 4))
print(Cat().sound())
